def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_d = n - opp_c
    my_d = n - my_c
    last_me, last_opp = history[-1]

    if n >= 99:
        return 'D'
    if opp_c / n < 0.2:
        return 'D'

    if n >= 2:
        prev_me, prev_opp = history[-2]
        if last_me != last_opp and prev_me != prev_opp and last_me != prev_me:
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            if opp_c > n * 0.8 and n > 10:
                return 'D'
            return 'C'
        else:
            if opp_c > n * 0.9 and n > 15 and rng.random() < 0.1:
                return 'D'
            return 'C'
    else:
        if last_me == 'C':
            if opp_c > n * 0.7 and opp_d <= 2:
                return 'C'
            return 'D'
        else:
            streak = 0
            for h in reversed(history):
                if h[1] == 'D':
                    streak += 1
                else:
                    break
            if streak >= 3 and opp_c > n * 0.3:
                return 'C'
            if opp_c > n * 0.8 and streak >= 2:
                return 'C'
            return 'D'
